// Read the decoded error attributes from the Problem binary_sensor.
// The exact path can vary slightly between node-red-contrib-home-assistant-websocket
// versions, so this checks a few known shapes defensively - use the
// 'Raw event (debug)' sidebar output to confirm which one applies to you.
const attrs =
    (msg.data && msg.data.event && msg.data.event.new_state && msg.data.event.new_state.attributes) ||
    (msg.data && msg.data.new_state && msg.data.new_state.attributes) ||
    (msg.data && msg.data.entity && msg.data.entity.attributes) ||
    {};

const code = attrs.code || "unknown";
const description = attrs.description || "No description available";

// TODO: replace with your own Telegram chat id (a number or string).
msg.chatId = "REPLACE_WITH_YOUR_TELEGRAM_CHAT_ID";

msg.payload =
    "⚠️ Creality SPARKX - printer error\n" +
    "Code: " + code + "\n" +
    "Description: " + description;

return msg;
